# 1. Создаем целевую директорию
$targetDir = ".venv\Lib\site-packages\_dick_cpp"
if (-not (Test-Path $targetDir)) {
    New-Item -ItemType Directory -Path $targetDir -Force | Out-Null
}

# 2. Base64-строки с содержимым файлов (гарантированно не ломаются при копировании в консоль Windows)
$initBase64 = "IyAudmVudlxMaWJcc2l0ZS1wYWNrYWdlc1xfZGlja19jcHBcX19pbml0X18ucHkNCmZyb20gLmRpY2tfd3JhcHBlciBpbXBvcnQgZXh0cmFjdG9yLCB0b19hc2NpaSwgbWFrZV9ncmFkaWVudA0KX19hbGxfXyA9IFsiZXh0cmFjdG9yIiwgInRvX2FzY2lpIiwgIm1ha2VfZ3JhZGllbnQiXQ=="

$wrapperBase64 = ""

# 3. Декодируем Base64 и сохраняем файлы в чистом UTF-8 (без BOM, как любит Python)
$initBytes = [System.Convert]::FromBase64String($initBase64)
[System.IO.File]::WriteAllText("$targetDir\__init__.py", [System.Text.Encoding]::UTF8.GetString($initBytes), [System.Text.UTF8Encoding]::new($false))

$wrapperBytes = [System.Convert]::FromBase64String($wrapperBase64)
[System.IO.File]::WriteAllText("$targetDir\dick_wrapper.py", [System.Text.Encoding]::UTF8.GetString($wrapperBytes), [System.Text.UTF8Encoding]::new($false))

Write-Host "Файлы успешно созданы с правильной UTF-8 кодировкой в $targetDir" -ForegroundColor Green